@Library('shared-jenkins-library@master') _

properties([
    parameters(getJenkinsJobParameters())
])

pipeline {
    agent any
    tools {
        maven 'Maven-3.5.0'
    }
    options {
        gitLabConnection('Gitlab')
    }

    environment {
        SHARED_MODULES_GIT_URL = 'ssh://git@my.gitserver.com:5555/cloudops/IaaC/shared-modules.git'
        NOTIFICATION_RECIPIENT = 'IoT Platform Deployments - TGCS-SaaS <04a66bd9.tecglobal.onmicrosoft.com@amer.teams.ms>'
    }

    stages {
        stage('Azure Resources MR Validation') { 
            when {
                expression {
                    return isAzureValidationBuild() && envUtils.hasTerraformChanges()
                }
            }
            steps {
                script {
                    updateGitlabCommitStatus name: 'azure-mr-validation', state: 'running'
                    echo "within stage(Azure Resources MR Validation)"

                    def validationEnvironment = getMrValidationEnvironment()
                    def validationBranch = getMrValidationBranch()

                    withCredentials([azureServicePrincipal(get_service_principal(validationEnvironment))]) {
                        catchError(buildResult: 'FAILURE', stageResult: 'FAILURE') {
                            def shared_target = 'shared-modules'
                            def target = 'terraform'

                            sshagent(['jenkins-gitlab-ssh']) {
                                def sharedModulesBranch = resolveSharedModulesBranch(validationBranch)
                                checkout_code(env.SHARED_MODULES_GIT_URL, sharedModulesBranch, shared_target)
                                checkout_code('ssh://git@my.gitserver.com:5555/cloudops/IaaC/iot-platform-iac.git', validationBranch, target)
                            }

                            withCredentials([string(credentialsId: 'CERT_PWD', variable: 'test')]) {
                                def tfEnvironment = validationEnvironment.toLowerCase()
                                def appSettings = readJSON text: params.APP_SETTINGS_JSON
                                appSettings = [:] + appSettings
                                def appSettingsJson = '{' + appSettings.collect { key, value -> "\"${key}\":\"${value}\"" }.join(',') + '}'
                                def iotFunctionAppJson = '{"ftp_state":"FtpsOnly","enabled_builtin_logging":true,"python_version":"3.12","identity_type":"SystemAssigned","container_use_managed_identity":false,"client_certificate_mode":"Optional","enable_vnet_integration":true,"app_settings":' + appSettingsJson + '}'
                                def vars = [
                                    "iot_function_app": iotFunctionAppJson
                                ]
                                def co_var = ''
                                vars.each { entry ->
                                    co_var = co_var + "-var '" + entry.key + "=" + entry.value + "' "
                                }
                                writeFile file: 'markup_image_versions.json', text: params.MARKUP_IMAGE_VERSIONS
                                def tfVarImageVersions = sh(
                                    script: 'python3 -c "import json,sys; print(json.dumps(json.load(sys.stdin)))" < markup_image_versions.json',
                                    returnStdout: true
                                ).trim()
                                def tagsJson = """
                                {
                                    "git_commit": "${env.GIT_COMMIT}",
                                    "git_branch": "${env.GIT_BRANCH}"
                                }
                                """.stripIndent().trim().replace('\n', ' ')
                                try {
                                    tagsJsonValid = readJSON text: tagsJson
                                } catch (e) {
                                    echo "Caught: ${e} '${tagsJson}' not valid JSON."
                                    currentBuild.result = 'FAILURE'
                                }

                                withEnv([
                                    "ARM_CLIENT_ID=${env.AZURE_CLIENT_ID}",
                                    "ARM_CLIENT_SECRET=${env.AZURE_CLIENT_SECRET}",
                                    "ARM_TENANT_ID=${env.AZURE_TENANT_ID}",
                                    "ARM_SUBSCRIPTION_ID=${env.AZURE_SUBSCRIPTION_ID}",
                                    "TF_VAR_image_versions=${tfVarImageVersions}",
                                    "TF_VAR_optional_tags=${tagsJson}"
                                ]) {
                                    sh '''
                                    set -eu
                                    az login --service-principal -u "${AZURE_CLIENT_ID}" -p "${AZURE_CLIENT_SECRET}" -t "${AZURE_TENANT_ID}" -o table
                                    az account set -s "${AZURE_SUBSCRIPTION_ID}"

                                    az provider register --namespace Microsoft.AppPlatform
                                    az provider register --namespace Microsoft.ContainerService
                                    '''

                                    dir("${target}/tf") {
                                        sh '''
                                        set -eu
                                        pwd
                                        terraform --version
                                        terraform fmt -check -recursive -no-color
                                        rm -f tf.plan tfplan.txt
                                        terraform init -input=false -reconfigure -backend-config=environments/''' + tfEnvironment + '''/backend.conf
                                        terraform validate -no-color
                                        set +e
                                        terraform plan -detailed-exitcode -no-color -input=false --var-file=environments/''' + tfEnvironment + '''/terraform.tfvars ''' + co_var + ''' -out tf.plan > tfplan.txt 2>&1
                                        rc=$?
                                        set -e
                                        if [ "$rc" -ne 0 ] && [ "$rc" -ne 2 ]; then
                                            cat tfplan.txt
                                            exit "$rc"
                                        fi
                                        cat tfplan.txt
                                        '''
                                    }

                                    archiveArtifacts artifacts: "${target}/tf/tfplan.txt", fingerprint: true
                                }
                            }
                        }
                    }
                }
            }
            post {
                success {
                    updateGitlabCommitStatus name: 'azure-mr-validation', state: 'success'
                }
                failure {
                    updateGitlabCommitStatus name: 'azure-mr-validation', state: 'failed'
                }
                always {
                    script {
                        safeNotifyMgr(env.STAGE_NAME)
                    }
                }
            }
        }
        stage('Credentials Service') {
            when {
                expression {
                    return !isAzureValidationBuild() && params.Playbook?.equals('Credentials Service');
                }
            }
            steps {
                script {
                    catchError(buildResult: 'FAILURE', stageResult: 'FAILURE') {
