                                        ]
                                def co_var = ''
                                vars.each{entry ->
                                    co_var = co_var + "-var '" + entry.key + "=" + entry.value + "' "
                                }
                                writeFile file: 'markup_image_versions.json', text: params.MARKUP_IMAGE_VERSIONS
                                def tfVarImageVersions = sh(
                                    script: 'python3 -c "import json,sys; print(json.dumps(json.load(sys.stdin)))" < markup_image_versions.json',
                                    returnStdout: true
                                ).trim()
                                def tagsJson = """
                                {
                                    "git_commit": "${env.GIT_COMMIT}",
                                    "git_branch": "${env.GIT_BRANCH}"
                                }
                                """.stripIndent().trim().replace('\n', ' ')
                                try {
                                    tagsJsonValid = readJSON text: tagsJson
                                } catch (e) {
                                    echo "Caught: ${e} '${tagsJson}' not valid JSON."
                                    currentBuild.result = 'FAILURE'
                                }
                                withEnv([
                                    "ARM_CLIENT_ID=${env.AZURE_CLIENT_ID}",
                                    "ARM_CLIENT_SECRET=${env.AZURE_CLIENT_SECRET}",
                                    "ARM_TENANT_ID=${env.AZURE_TENANT_ID}",
                                    "ARM_SUBSCRIPTION_ID=${env.AZURE_SUBSCRIPTION_ID}",
