                                        terraform init -input=false -reconfigure -backend-config=environments/''' + tfEnvironment + '''/backend.conf
                                        terraform plan -no-color -input=false --var-file=environments/''' + tfEnvironment + '''/terraform.tfvars ''' + co_var + ''' -out tf.plan
