def safeNotifyMgr(String stageName) {
    try {
        notifyMgr(stageName)
    } catch(e) {
        println "Email notification failed for stage '${stageName}': ${e}"
    }
}

def getJenkinsJobParameters() {
    return [
        choice(name: 'ENVIRONMENT', choices: ['DEV', 'QA', 'STAGE', 'PROD'], description: 'Select the environment to run on'),
        [
            $class: 'DynamicReferenceParameter',
            choiceType: 'ET_FORMATTED_HTML',
            name: 'BRANCH',
            description: 'Git branch name of the components to build and deploy, derived from the selected environment.',
            omitValueField: true,
            referencedParameters: 'ENVIRONMENT',
            script: [
                $class: 'GroovyScript',
                fallbackScript: [
                    classpath: [],
                    sandbox: true,
                    script: 'return "Unable to resolve branch for the selected environment."'
                ],
                script: [
                    classpath: [],
                    sandbox: true,
                    script: getBranchGroovyScript()
                ]
            ]
        ],
        choice(name: 'Playbook', choices: [
            '',
            'Credentials Service',
            'Device Management Service',
            'Firmware Service',
            'Key Rotation Service',
            'Locations Service',
            'Telemetry Service',
            'Remote Control Service',
            'Azure Resources',
            'Notification Service',
            'Markups Function App',
            'IoT Portal'
        ], description: 'Choose a service to deploy'),
        [
            $class: 'DynamicReferenceParameter',
            choiceType: 'ET_FORMATTED_HTML',
            name: 'Parameters',
            description: 'Service-specific deployment parameters generated from the selected environment and service.',
            omitValueField: true,
            referencedParameters: 'Playbook,ENVIRONMENT,REGION_NAME',
            script: [
                $class: 'GroovyScript',
                fallbackScript: [
                    classpath: [],
                    sandbox: true,
                    script: 'return "Unable to render deployment parameters."'
                ],
                script: [
                    classpath: [],
                    sandbox: true,
                    script: getParametersGroovyScript()
                ]
            ]
        ],
        [
            $class: 'DynamicReferenceParameter',
            choiceType: 'ET_FORMATTED_HTML',
            name: 'RESOURCE_GROUP',
            description: 'The resource group under which the IoT azure resources were created, derived from the selected environment and region.',
            omitValueField: true,
            referencedParameters: 'ENVIRONMENT,REGION_NAME',
            script: [
                $class: 'GroovyScript',
                fallbackScript: [
                    classpath: [],
                    sandbox: true,
                    script: 'return "Unable to resolve resource group for the selected environment/region."'
                ],
                script: [
                    classpath: [],
                    sandbox: true,
                    script: getResourceGroupGroovyScript()
                ]
            ]
        ],
        choice(name: 'REGION_NAME', choices: ['eastus', 'westus', 'centralus', 'northcentralus', 'southcentralus'], description: 'The azure region for the resource group'),
        text(name: 'APP_SETTINGS_JSON', defaultValue: '''{
  "API_USERNAME": "apiapp",
  "API_PASSWORD": "",
  "CAMERA_HEALTHCHECK_SCHEDULE": "0 10 12 * * *",
  "EMAIL_SENDER": "DoNotReply@4b91465e-ca73-4113-b214-b1188a352fdf.azurecomm.net",
  "NOTIFICATION_API_USERNAME": "tgcs-admin",
  "NOTIFICATION_API_PASSWORD": "",
  "NOTIFICATIONS_SCHEDULE": "0 10 12 * * *"
}''', description: 'JSON object for Function App health check service settings'),
        text(name: 'MARKUP_IMAGE_VERSIONS',
        defaultValue: '''{
    "iot-markups-inference": ""
}''',
        description: 'JSON string containing markup image version for deployment.')
    ]
}

