def trimToNull(value) {
    def trimmed = value?.trim()
    return trimmed ? trimmed : null
}

def isMergeRequestValidationBuild() {
    def mrState = trimToNull(env.gitlabMergeRequestState)?.toLowerCase()
    def hasMrContext = trimToNull(env.gitlabMergeRequestIid) ||
        (trimToNull(env.gitlabSourceBranch) && trimToNull(env.gitlabTargetBranch))

    if (hasMrContext) {
        return true
    }

    return mrState && !['merged', 'closed'].contains(mrState)
}

def isGitlabPushBuild() {
    return trimToNull(env.gitlabActionType)?.toUpperCase() == 'PUSH'
}

def isAzureValidationBuild() {
    return isMergeRequestValidationBuild() || isGitlabPushBuild()
}

