def isUnsetParameterValue(value) {
    def normalized = trimToNull(value?.toString())
    if (!normalized) {
        return true
    }

    def placeholders = [
        'Choose service version',
        'Choose artifact version',
        'Please select an environment and service',
        'Please select an environment and service;'
    ]

    return placeholders.contains(normalized)
}

