def parseConfiguredDeploymentParameters(playbook) {
    def configuredParameters = trimToNull(params.Parameters)
    if (!configuredParameters) {
        return [:]
    }

    def values = configuredParameters.split(',', -1).collect { it.trim() }
    if (values && values[-1] == '') {
        values = values[0..-2]
    }

    if (getServicePlaybooks().contains(playbook)) {
        if (values.size() != 3) {
            error("Parameters for '${playbook}' must contain 3 values: service name, artifact URL, keyvault URL.")
        }
        return [
            serviceName: values[0],
            artifactUrl: values[1],
            keyvaultUrl: values[2]
        ]
    }

    if (playbook == 'Notification Service') {
        if (values.size() != 2) {
            error("Parameters for 'Notification Service' must contain 2 values: artifact URL, function app name.")
        }
        return [
            artifactUrl: values[0],
            functionAppName: values[1]
        ]
    }

    if (playbook == 'Markups Function App') {
        if (values.size() != 3) {
            error("Parameters for 'Markups Function App' must contain 3 values: image version, artifact URL, function app name.")
        }
        return [
            imageVersion: values[0],
            artifactUrl: values[1],
            functionAppName: values[2]
        ]
    }

    return [:]
}

