def validateDeploymentConfig(playbook, config) {
    def requiredFieldsByPlaybook = [
        'Credentials Service'     : ['serviceName', 'artifactUrl', 'keyvaultUrl'],
        'Device Management Service': ['serviceName', 'artifactUrl', 'keyvaultUrl'],
        'Firmware Service'        : ['serviceName', 'artifactUrl', 'keyvaultUrl'],
        'Key Rotation Service'    : ['serviceName', 'artifactUrl', 'keyvaultUrl'],
        'Locations Service'       : ['serviceName', 'artifactUrl', 'keyvaultUrl'],
        'Telemetry Service'       : ['serviceName', 'artifactUrl', 'keyvaultUrl'],
        'Remote Control Service'  : ['serviceName', 'artifactUrl', 'keyvaultUrl'],
        'IoT Portal'              : ['serviceName', 'artifactUrl', 'keyvaultUrl'],
        'Notification Service'    : ['artifactUrl', 'functionAppName'],
        'Markups Function App'    : ['imageVersion', 'artifactUrl', 'functionAppName']
    ]

    def missingFields = (requiredFieldsByPlaybook[playbook] ?: []).findAll { fieldName ->
        isUnsetParameterValue(config[fieldName])
    }

    if (!missingFields.isEmpty()) {
        error("Missing deployment parameters for '${playbook}': ${missingFields.join(', ')}")
    }
}

def getResolvedDeploymentConfig() {
    def playbook = params.Playbook
    def defaults = getDefaultDeploymentConfig(playbook)
    def configured = parseConfiguredDeploymentParameters(playbook)
    def config = [:] + defaults + configured

    validateDeploymentConfig(playbook, config)
    return config
}

