def resolveSharedModulesBranch(String requestedBranch = params.BRANCH?.trim()) {
    def availableBranchesOutput = sh(
        script: "git ls-remote --heads '${env.SHARED_MODULES_GIT_URL}'",
        returnStdout: true
    ).trim()

    def availableBranches = availableBranchesOutput
        .split('\n')
        .findAll { it?.trim() }
        .collect { line ->
            def parts = line.tokenize()
            def ref = parts.size() > 1 ? parts[1] : ''
            return ref.replaceFirst('^refs/heads/', '')
        }

    if (requestedBranch && availableBranches.contains(requestedBranch)) {
        return requestedBranch
    }

    if (requestedBranch?.equalsIgnoreCase('QA')) {
        if (availableBranches.contains('QA')) {
            return 'QA'
        }
        if (availableBranches.contains('qa')) {
            return 'qa'
        }
        if (availableBranches.contains('master')) {
            return 'master'
        }
        error('QA fallback branch master not found in shared-modules repo')
    }

    if (requestedBranch == 'master') {
        if (availableBranches.contains('master')) {
            return 'master'
        }
        error('master branch not found in shared-modules repo')
    }

    if (requestedBranch?.startsWith('release-')) {
        if (availableBranches.contains(requestedBranch)) {
            return requestedBranch
        }
        if (availableBranches.contains('master')) {
            return 'master'
        }
        error('release fallback branch master not found in shared-modules repo')
    }

    if (availableBranches.contains('develop')) {
        return 'develop'
    }

    error('develop branch not found in shared-modules repo')
}


