def deploy_markups_function_app() {
    // Parameters format: "IMAGE_VERSION,SRC_URL,FUNCTION_APP_NAME"
    // IMAGE_VERSION: tag to pull from eleracicdacr and push to target ACR, e.g. "1.2.3"
    // SRC_URL:       download URL for the function app zip artifact
    // FUNCTION_APP_NAME: name of the Azure Function App to deploy the zip to
    def config = getResolvedDeploymentConfig()
    def image_version = config.imageVersion
    def src_url = config.artifactUrl
    def function_app_name = config.functionAppName

    def file_name = src_url.substring(src_url.lastIndexOf('/') + 1)
    def buildId = file_name.lastIndexOf('.') > 0 ? file_name.substring(0, file_name.lastIndexOf('.')) : file_name
    println "Deploying Markups Function App: image=${image_version}, zip=${file_name}, app=${function_app_name}"

    withCredentials([azureServicePrincipal(get_service_principal(ENVIRONMENT))]) {
        withCredentials([
            usernamePassword(credentialsId: 'ELERA_CICD_ACR',
                             usernameVariable: 'SRC_ACR_USERNAME',
                             passwordVariable: 'SRC_ACR_PASSWORD')
        ]) {
            sh '''#!/usr/bin/env bash
                set -e

                echo "Logging in to Azure..."
                az login --service-principal \
                    -u "${AZURE_CLIENT_ID}" \
                    -p "${AZURE_CLIENT_SECRET}" \
                    -t "${AZURE_TENANT_ID}"
                az account set -s "${AZURE_SUBSCRIPTION_ID}"

                echo "Resolving target ACR..."
                TARGET_ACR=$(az acr list \
                    --resource-group "${RESOURCE_GROUP}" \
                    --subscription "${AZURE_SUBSCRIPTION_ID}" \
                    --query "[0].name" -o tsv)
                TARGET_ACR_SERVER=$(az acr show --name "${TARGET_ACR}" --resource-group "${RESOURCE_GROUP}" --subscription "${AZURE_SUBSCRIPTION_ID}" --query "loginServer" -o tsv)
                echo "Target ACR: ${TARGET_ACR} (${TARGET_ACR_SERVER})"

                echo "Pulling iot-markups-inference:''' + image_version + ''' from eleracicdacr"
                docker login eleracicd.azurecr.io \
                    --username "${SRC_ACR_USERNAME}" \
                    --password "${SRC_ACR_PASSWORD}"
                docker pull "eleracicd.azurecr.io/iot-markups-inference:''' + image_version + '''"

                echo "Tagging and pushing iot-markups-inference:''' + image_version + ''' to ${TARGET_ACR_SERVER}"
                az acr login --name "${TARGET_ACR}" --resource-group "${RESOURCE_GROUP}" --subscription "${AZURE_SUBSCRIPTION_ID}"
                docker tag "eleracicd.azurecr.io/iot-markups-inference:''' + image_version + '''" \
                    "${TARGET_ACR_SERVER}/iot-markups-inference:''' + image_version + '''"
                docker push "${TARGET_ACR_SERVER}/iot-markups-inference:''' + image_version + '''"

                echo "Cleaning up local images..."
                docker rmi "eleracicd.azurecr.io/iot-markups-inference:''' + image_version + '''" \
                    "${TARGET_ACR_SERVER}/iot-markups-inference:''' + image_version + '''" || true

                echo "Updating BATCH_CONTAINER_IMAGE app setting on ''' + function_app_name + '''"
                az functionapp config appsettings set \
                    --resource-group "${RESOURCE_GROUP}" \
                    --name ''' + function_app_name + ''' \
                    --settings "BATCH_CONTAINER_IMAGE=iot-markups-inference:''' + image_version + '''"

                echo "Deploying ''' + file_name + ''' to ''' + function_app_name + '''"
                curl -k -O ''' + src_url + '''
                az functionapp deployment source config-zip \
                    --resource-group "${RESOURCE_GROUP}" \
                    --name ''' + function_app_name + ''' \
                    --src ''' + file_name + '''

                echo "Tagging ''' + function_app_name + ''' with build_id=''' + buildId + '''"
                az functionapp update \
                    --resource-group "${RESOURCE_GROUP}" \
                    --name ''' + function_app_name + ''' \
                    --set tags.build_id=''' + buildId + '''

                echo "Cleaning up zip artifact..."
                rm -f ''' + file_name + '''
                az logout
                echo "Markups inference deployment complete."
            '''
        }
    }

    println "Markups Function App deployment completed: ${function_app_name}"
}

